//! HFS / HFS+ catalog-name ordering, which a writer must reproduce exactly or Mac OS reports
//! a damaged B-tree.
//!
//! - [`hfs_unicode`]: HFS+ case folding (Apple TN1150's `FastUnicodeCompare` mapping) and the
//!   Unicode 3.2 canonical decomposition HFS+ stores names in, with TN1150's exclusions.
//! - [`collate`]: `compare_hfsplus_keys` on top of those, and `compare_hfs_keys` with each Mac
//!   Roman byte's rank under Apple's `RelString`.
//!
//! The tables are generated by `scripts/gen-hfsplus-tables.py` and `scripts/gen-hfs-charorder.py`;
//! the README says where their inputs come from and how they were checked against macOS.

pub mod collate;
pub mod hfs_unicode;

mod hfs_charorder;
mod hfsplus_tables;
